style.css:
@-moz-document domain("deepl.com") {
/* 1. Sobrescritura del sistema de tokens (DeepL UI) */
  :root, html, body {
    --dui-color-background-app: #121417 !important;
    --dui-color-background-surface: #1c1f24 !important;
    --dui-color-background-surface-raised: #252a31 !important;
    --dui-color-background-surface-canvas: #121417 !important;
    --dui-color-background-surface-secondary: #16181d !important;
    --dui-color-background-surface-canvas-secondary: #16181d !important;
    --dui-color-background-surface-neutral: #2e343d !important;
    --dui-color-background-surface-neutral-muted: #252a31 !important;
    
    --dui-color-background-action: #1c1f24 !important;
    --dui-color-background-action-basic: #1c1f24 !important;
    --dui-color-background-action-basic-hover: #2a3038 !important;
    --dui-color-background-action-basic-pressed: #343b46 !important;
    --dui-color-background-action-ghost: transparent !important;
    --dui-color-background-action-ghost-hover: rgba(255, 255, 255, 0.08) !important;
    
    --dui-color-text-default: #e6edf3 !important;
    --dui-color-text-muted: #9aa5b1 !important;
    --dui-color-text-action: #e6edf3 !important;
    --dui-color-text-action-basic: #e6edf3 !important;
    --dui-color-text-brand: #e6edf3 !important;
    
    --dui-color-border-default: #30363d !important;
    --dui-color-border-action-basic-default: #30363d !important;
    color-scheme: dark !important;
  }

  /* 2. Fondo general y estructura */
  html, body, main,
  [data-testid="translator"],
  .bg-surface,
  .bg-surface-canvas,
  .bg-surface-canvas-secondary,
  .bg-action-basic,
  .bg-white {
    background-color: #121417 !important;
    color: #e6edf3 !important;
  }

  /* 3. Barra superior de navegación (Header) */
  header, nav, [role="banner"], [data-testid*="top-navigation"] {
    background-color: #1c1f24 !important;
    border-color: #30363d !important;
  }

  header a, nav a, header button {
    color: #e6edf3 !important;
  }

  /* 4. Pestañas superiores (Traducir texto, Traducir archivos, voz, etc.) */
  [data-layout-id="translatorTabList"],
  [data-layout-id="translatorTabList"] > div {
    background-color: transparent !important;
  }

  [data-layout-id="translatorTabList"] a,
  [data-layout-id="translatorTabList"] button,
  [data-testid*="doctrans-tabs"],
  [data-testid*="storefront-tabs"] {
    background-color: #1c1f24 !important;
    color: #9aa5b1 !important;
    border: 1px solid #30363d !important;
    border-radius: 8px !important;
  }

  [data-layout-id="translatorTabList"] a:hover,
  [data-layout-id="translatorTabList"] button:hover {
    background-color: #262b33 !important;
    color: #ffffff !important;
  }

  /* Pestaña activa seleccionada */
  [data-layout-id="translatorTabList"] a.is-active,
  [data-layout-id="translatorTabList"] a[aria-current="page"],
  [data-layout-id="translatorTabList"] [aria-selected="true"] {
    background-color: #252a31 !important;
    color: #60a5fa !important;
    border-color: #3b82f6 !important;
    font-weight: 600 !important;
  }

  /* 5. Barra de idiomas superior (la franja blanca de tu captura) */
  [data-layout-id="editor-layout-toolbar"],
  [data-layout-id="editor-layout-toolbar"] > div,
  [data-layout-id="toolbarAdditionalArea"] {
    background-color: #1c1f24 !important;
    border-color: #30363d !important;
    color: #e6edf3 !important;
  }

  /* Botones dentro de la barra de idiomas */
  [data-testid="translator-source-lang-btn"],
  [data-testid="translator-target-lang-btn"],
  [data-layout-id="editor-layout-toolbar"] button,
  .Button.as-ghost {
    background-color: #262b33 !important;
    color: #e6edf3 !important;
    border: 1px solid #30363d !important;
  }

  [data-layout-id="editor-layout-toolbar"] button:hover,
  .Button.as-ghost:hover {
    background-color: #323842 !important;
    border-color: #484f58 !important;
  }

  /* 6. Áreas de entrada de texto (Source y Target) */
  d-textarea,
  textarea,
  [data-testid="translator-source-input"],
  [data-testid="translator-target-input"],
  .lmt__textarea_container {
    background-color: #16181d !important;
    color: #f0f3f6 !important;
    border-color: #30363d !important;
  }

  /* 7. Sección inferior del Diccionario (la franja blanca inferior de tu captura) */
  [data-layout-id="editor-layout-footer"],
  [data-layout-id="dictionarySection"],
  [data-layout-id="editor-layout-action-bar"] {
    background-color: #1c1f24 !important;
    border-color: #30363d !important;
    color: #e6edf3 !important;
  }

  [data-layout-id="dictionarySection"] h3,
  [data-layout-id="dictionarySection"] div,
  #dictionary-header {
    color: #e6edf3 !important;
  }

  /* 8. Textos y bordes generales */
  .text-default,
  .text-gray-900,
  .text-slate-900,
  .text-black {
    color: #e6edf3 !important;
  }

  .text-muted,
  .text-gray-600 {
    color: #9aa5b1 !important;
  }

  .border-default,
  [class*="border-default"] {
    border-color: #30363d !important;
  }

  /* 9. Desplegables de selección de idioma y popups */
  [role="menu"],
  [role="listbox"],
  [role="dialog"],
  div[data-testid*="menu"],
  div[data-testid*="popover"],
  div[class*="flyoutPanel"] {
    background-color: #1c1f24 !important;
    color: #e6edf3 !important;
    border: 1px solid #30363d !important;
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.7) !important;
  }

  [role="option"]:hover,
  [role="option"][aria-selected="true"] {
    background-color: #2b323c !important;
    color: #60a5fa !important;
  }

  /* 10. Scrollbar estético */
  ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  ::-webkit-scrollbar-track {
    background: #121417;
  }
  ::-webkit-scrollbar-thumb {
    background: #30363d;
    border-radius: 4px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #484f58;
  }
}
